export function notificationText(lang:Lang,kind:string|null,title:string,body:string){
 const t=NOTIFICATION_TRANSLATIONS[lang];
 if(kind==='new_message') return {title:t.newMessageTitle,body:t.newMessageBody};
 if(kind==='new_booking') return {title:t.newBookingTitle,body:t.newBookingBody};
 if(kind==='new_review') return {title:t.newReviewTitle,body:t.newReviewBody};
 return {title,body};
}

